import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.CeXt7FPx.js";const k=JSON.parse('{"title":"New projects","description":"","frontmatter":{},"headers":[],"relativePath":"guide/new-projects.md","filePath":"guide/new-projects.md"}'),n={name:"guide/new-projects.md"};function o(h,s,r,d,l,p){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="new-projects" tabindex="-1">New projects <a class="header-anchor" href="#new-projects" aria-label="Permalink to &quot;New projects&quot;">​</a></h1><p><code>tiffin new</code> makes a project in a folder of its own and serves it at <code>&lt;name&gt;.test</code>: a JavaScript stack, a blank HTML page, a Laravel app, a WordPress site or a cloned repository. Whatever it needs (Node, PHP, Composer or WP-CLI, a database server) is installed on the way. In the app, it is <strong>New project…</strong> on the Projects screen; it suggests your first parked folder.</p><h2 id="laravel" tabindex="-1">Laravel <a class="header-anchor" href="#laravel" aria-label="Permalink to &quot;Laravel&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laravel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # SQLite, in this folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laravel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --npm</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # a starter kit, built</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laravel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mariadb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8.4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # a database server</span></span></code></pre></div><p>It runs <code>composer create-project</code> (of <code>laravel/laravel</code>, or of the starter kit: <code>react</code>, <code>vue</code>, <code>livewire</code> or <code>svelte</code>), which is what the Laravel installer does, then:</p><ol><li>writes a <code>tiffin.toml</code> with the project&#39;s PHP, its database server and database (unless it uses SQLite) and its site;</li><li>brings it up, as <a href="/tiffin/guide/projects"><code>tiffin up</code></a> does: the server is started, the database created and <code>shop.test</code> served;</li><li>sets <code>APP_URL</code> and the <code>DB_*</code> lines in <code>.env</code>, then runs <code>php artisan migrate</code>;</li><li>with <code>--npm</code>, runs <code>npm install</code> and <code>npm run build</code> with Tiffin&#39;s Node.</li></ol><h2 id="wordpress" tabindex="-1">WordPress <a class="header-anchor" href="#wordpress" aria-label="Permalink to &quot;WordPress&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wordpress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My Blog&quot;</span></span></code></pre></div><p>It writes the <code>tiffin.toml</code> (PHP, MariaDB or <code>--db mysql</code> with a <code>blog</code> database, the site), brings it up, then uses WP-CLI to download WordPress, write <code>wp-config.php</code> and install it. The administrator is <code>admin</code> (<code>--admin-user</code>) with a random password, printed at the end, or the one you give with <code>--admin-password</code>. Log in at <code>http://blog.test/wp-admin</code>. WordPress sends no mail at install.</p><p>In the app, <strong>New project…</strong> opens a searchable gallery with all of these in one place: four tiles — JavaScript, PHP, Static HTML and Clone. The JavaScript form has a framework selector (everything in <code>tiffin new --list</code>) and a Node version selector with every available release; the PHP form picks Laravel or WordPress. Each section therefore takes one short form instead of overflowing the dialog with cards. Pick one, type a name and a folder, and the form shows only that choice&#39;s options. When it is done, the dialog offers Open site, Open folder and Copy URL, as well as the WordPress login card.</p><h2 id="see-it-first" tabindex="-1">See it first <a class="header-anchor" href="#see-it-first" aria-label="Permalink to &quot;See it first&quot;">​</a></h2><p><code>--dry-run</code> shows what <code>tiffin new</code> would do, and does none of it: the runtimes it would use (installed, or downloaded first), the commands it would run, the files it would write, and the command to make the same project. <code>--json</code> prints the same as JSON. The WordPress password is never in it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laravel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>In the app, the New project form shows the same plan under <strong>What Tiffin will do</strong> as you change the options, with a button to copy the command. A folder that is there already shows as a warning.</p><h2 id="javascript-and-other-stacks" tabindex="-1">JavaScript and other stacks <a class="header-anchor" href="#javascript-and-other-stacks" aria-label="Permalink to &quot;JavaScript and other stacks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react-vite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # plain React, with Vite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tailwind=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static-html</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> landing</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # a blank index.html</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # every stack and its options</span></span></code></pre></div><p>The stacks are React (Vite), Next.js, Vue, Nuxt, SvelteKit, Astro, Node + Express, Bun + Hono and Static HTML. <code>tiffin new --list</code> shows their ids and the options each takes; pass one with <code>--opt key=value</code> (repeat it for more than one). By default a stack uses Tiffin&#39;s installed default Node (or Bun), or downloads the newest release if none is installed; <code>--node 22</code>, <code>--node 22.23.3</code> or <code>--node latest</code> chooses one. For a framework, Tiffin installs its Node (or Bun), runs the scaffolder, installs the packages, then writes a <code>tiffin.toml</code> with a <code>[site] proxy</code> to the dev server and a <code>[processes]</code> entry to keep it running, so <code>shop.test</code> has hot reload. Run <code>tiffin up</code> in the folder to bring it back after a restart; <code>tiffin proc</code> shows the dev server&#39;s state and logs. A dev server that is slow to answer is a warning: the project is still made.</p><p>Each project gets its own dev-server port. It starts with the framework&#39;s usual port (5173 for Vite, Vue and SvelteKit; 3000 for Next, Nuxt, Express and Hono; 4321 for Astro), and falls back to a free port in the 5200–5999 range when that port is already used by another project or process. The chosen port is written into the project&#39;s <code>package.json</code> scripts — <code>dev</code> and the prod script (<code>start</code> or <code>preview</code>) — so a later <code>npm run dev</code> (or <code>bun run dev</code>), or a prod run, binds exactly the port that <code>shop.test</code> forwards to. The <code>[processes] dev</code> entry runs that same script. Vite-based stacks use <code>--strictPort</code>: if something takes the port later, the dev server stops instead of silently moving and leaving the <code>.test</code> site pointing at the wrong port.</p><p>Static HTML writes an <code>index.html</code> and a <code>tiffin.toml</code> with just the site: no runtime, no dev server, nothing to install. It is served as-is, as a parked folder would be.</p><h2 id="clone-a-repository" tabindex="-1">Clone a repository <a class="header-anchor" href="#clone-a-repository" aria-label="Permalink to &quot;Clone a repository&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:acme/shop.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:acme/shop.git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop-staging</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/acme/shop.git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span></code></pre></div><p>It clones into <code>&lt;name&gt;</code> (the repository&#39;s name, or <code>--name</code>) in the current folder (<code>--dir</code>), then links it as <code>&lt;name&gt;.test</code>, or brings up its <code>tiffin.toml</code> if it has one. A Laravel project is then set up in the background (<code>composer install</code>, <code>.env</code>, the key, npm). Git comes from Tiffin&#39;s own package on Windows and from the system elsewhere.</p><p>Over SSH, Tiffin picks the <a href="/tiffin/guide/ssh">SSH identity</a> for the host (or the one you name with <code>--identity</code>) and runs git with only that key. Host keys are checked strictly against Tiffin&#39;s own file: a host it has not seen is refused and its fingerprint shown, then <code>tiffin ssh trust-host &lt;host&gt; --fingerprint SHA256:…</code> once you have checked it. A key you already trust in <code>~/.ssh/known_hosts</code> is carried over without asking. If the clone fails, the folder is removed.</p><h2 id="when-something-fails" tabindex="-1">When something fails <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;When something fails&quot;">​</a></h2><p>The output of each command is shown as it runs. If one fails, the folder stays as it is: delete it and try again, or fix the problem and run <code>tiffin up</code> in it. <code>--dir</code> makes the project somewhere other than the current folder; <code>--json</code> prints the steps and the result as JSON.</p>`,25)])])}const F=e(n,[["render",o]]);export{k as __pageData,F as default};
